                    </table>
                </div>
                <div>
                    <h3>Lowest Homicide Rates (2023)</h3>
                    <table>
                        <tr>
                            <th>Country</th>
                            <th>Rate</th>
                        </tr>
                        <tr class="highlight-green">
                            <td>Holy See</td>
                            <td>0.00</td>
